#include <stdarg.h>

#include "can.h"
#include "can_v_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean can_v_execute (UInt8 can_dev_count , ...)
{
  CRITICAL ;

  if (can_v_rx_lut_map_sw_to_hw ())
    {
      Lut_Map ** lut_map_table = can_v_rx_lut_map_hw_to_sw ()  ;

      can_v_rx_init_os_interface () ;

      can_v_vars.exec.lut_map_table = lut_map_table ;

      C_ENTER ;
        {
          va_list arg ;

          va_start (arg , can_dev_count) ;
            {
              while (can_dev_count--)
                {
                  can_dev_set_irq_rx (va_arg (arg , Can_Dev) , can_v_can_irq_service_rx) ;
                }
            }
          va_end (arg) ;
        }
      C_LEAVE ;

      return TRUE ;
    }

  return FALSE ;
}

